import React, { useState } from 'react';
import { toast } from 'react-toastify';

const UploadContent = ({ onUploadSuccess }) => {
    const [uploadType, setUploadType] = useState('youtube'); // 'youtube' or 'local'

    const handleUpload = (e) => {
        e.preventDefault();
        const title = e.target.elements.videoTitle.value;
        const description = e.target.elements.videoDescription.value;
        let url = '';
        let isLocal = false;

        if (uploadType === 'youtube') {
            url = e.target.elements.videoUrl.value;
        } else {
            const file = e.target.elements.videoFile.files[0];
            if (file) {
                // Validate that it's actually a video file
                if (!file.type.startsWith('video/')) {
                    toast.error('Please upload a video file only (MP4, MKV, AVI, etc.). Text/Document files are not allowed.');
                    return;
                }
                url = URL.createObjectURL(file);
                isLocal = true;
            }
        }

        if (url) {
            const newVideo = {
                id: Date.now(),
                title,
                url,
                description,
                isLocked: false,
                isLocal,
                quiz: {
                    question: e.target.elements.quizQuestion.value,
                    options: [
                        e.target.elements.option1.value,
                        e.target.elements.option2.value,
                        e.target.elements.option3.value,
                        e.target.elements.option4.value,
                    ],
                    correctAnswer: e.target.elements[`option${e.target.elements.correctOption.value}`].value
                }
            };

            onUploadSuccess(newVideo);
            e.target.reset();
        }
    };

    return (
        <div id="upload-section" className="upload-card" style={{ marginBottom: '30px' }}>
            <h2 className="card-title">Upload Content & Quiz</h2>
            <form onSubmit={handleUpload}>
                <div className="section-title" style={{ fontSize: '1.2rem', color: '#006D5B', marginTop: '10px', fontWeight: 'bold' }}>Video Details</div>

                <label className="form-label">Video Title</label>
                <input name="videoTitle" type="text" placeholder="e.g. Chapter 4: Database Design" className="form-input" required />

                <div style={{ marginTop: '15px' }}>
                    <label className="form-label">Upload Method</label>
                    <div style={{ display: 'flex', gap: '20px', marginBottom: '10px' }}>
                        <label style={{ display: 'flex', alignItems: 'center', gap: '5px', cursor: 'pointer' }}>
                            <input
                                type="radio"
                                name="uploadType"
                                value="youtube"
                                checked={uploadType === 'youtube'}
                                onChange={() => setUploadType('youtube')}
                            /> YouTube Link
                        </label>
                        <label style={{ display: 'flex', alignItems: 'center', gap: '5px', cursor: 'pointer' }}>
                            <input
                                type="radio"
                                name="uploadType"
                                value="local"
                                checked={uploadType === 'local'}
                                onChange={() => setUploadType('local')}
                            /> Local File
                        </label>
                    </div>
                </div>

                {uploadType === 'youtube' ? (
                    <>
                        <label className="form-label">Video URL (YouTube)</label>
                        <input name="videoUrl" type="url" placeholder="https://youtube.com/..." className="form-input" required />
                    </>
                ) : (
                    <>
                        <label className="form-label">Select Video File</label>
                        <input name="videoFile" type="file" accept="video/*" className="form-input" required />
                    </>
                )}

                <label className="form-label">Description</label>
                <textarea name="videoDescription" rows="2" className="form-input" required></textarea>

                <hr style={{ margin: '25px 0', border: 'none', borderTop: '1px solid #ddd' }} />

                <div className="section-title" style={{ fontSize: '1.2rem', color: '#006D5B', fontWeight: 'bold' }}>Quiz Details</div>

                <label className="form-label">Quiz Question</label>
                <input name="quizQuestion" type="text" placeholder="e.g. What is the main purpose of this topic?" className="form-input" required />

                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginTop: '10px' }}>
                    <div>
                        <label className="form-label">Option 1</label>
                        <input name="option1" type="text" className="form-input" required />
                    </div>
                    <div>
                        <label className="form-label">Option 2</label>
                        <input name="option2" type="text" className="form-input" required />
                    </div>
                    <div>
                        <label className="form-label">Option 3</label>
                        <input name="option3" type="text" className="form-input" required />
                    </div>
                    <div>
                        <label className="form-label">Option 4</label>
                        <input name="option4" type="text" className="form-input" required />
                    </div>
                </div>

                <label className="form-label">Correct Option</label>
                <select name="correctOption" className="form-input" required style={{ appearance: 'auto' }}>
                    <option value="1">Option 1</option>
                    <option value="2">Option 2</option>
                    <option value="3">Option 3</option>
                    <option value="4">Option 4</option>
                </select>

                <button type="submit" className="upload-btn" style={{ marginTop: '30px' }}>Upload Content & Quiz</button>
            </form>
        </div>
    );
};

export default UploadContent;
